mapper.select:

SELECT m.id, m.title, m.artist, m.album, m.youtube_url,
       m.location <-> #{qvec}::vector AS distance,

FROM music m
WHERE m.id <> #{id}
ORDER BY m.location <-> #{qvec}::vector
LIMIT #{k}

SELECT mg.music_id, g.name FROM music_genre mg JOIN genre g ON g.id = mg.genre_id WHERE mg.music_id IN
#{musicId}
ORDER BY mg.music_id, g.name
